import{_ as a,o as r,c as l,a2 as e}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"قانون حماية البيئة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/46-环境保护法.md","filePath":"ar/46-环境保护法.md","lastUpdated":null}'),d={name:"ar/46-环境保护法.md"};function i(o,t,h,n,s,b){return r(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="قانون-حماية-البيئة" tabindex="-1">قانون حماية البيئة <a class="header-anchor" href="#قانون-حماية-البيئة" aria-label="Permalink to &quot;قانون حماية البيئة&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>46</td></tr><tr><td>الوحدة</td><td>النظام القانوني وإطار الحوكمة</td></tr><tr><td>الكلمات المفتاحية</td><td>حماية البيئة، أصل الكون، التكافل البيئي، التنمية المستدامة، منع التلوث</td></tr></tbody></table><h2 id="أولاً-الغرض-التشريعي-والمبادئ-الأساسية" tabindex="-1">أولاً: الغرض التشريعي والمبادئ الأساسية <a class="header-anchor" href="#أولاً-الغرض-التشريعي-والمبادئ-الأساسية" aria-label="Permalink to &quot;أولاً: الغرض التشريعي والمبادئ الأساسية&quot;">​</a></h2><p><em>قانون حماية البيئة</em> أحد القوانين الخمسة المساندة لحضارة التكافل المرساة. يهدف إلى حماية البيئة الإيكولوجية وأصل الكون داخل كون هنغ يوان، وإرساء فلسفة الحوكمة البيئية القائمة على «التطور التكافلي، التنمية المستدامة»، ومنع تدمير النظام الإيكولوجي الكوني بالتنمية الافتراسية، وحماية أساس البقاء لتقدم عشرة آلاف عرق معاً.</p><p>يحدد هذا القانون المبادئ الأساسية التالية:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون</th></tr></thead><tbody><tr><td>حماية الأصل</td><td>أصل الكون أساس كل حياة وتطور؛ ويجب حمايته بالأولوية؛ ويُحظر الاستخراج التدميري</td></tr><tr><td>التكافل البيئي</td><td>الإنسان والطبيعة، وجميع الأعراق والنظم الإيكولوجية في علاقة تكافلية؛ وتدمير البيئة يعني تدمير أساس البقاء الذاتي</td></tr><tr><td>الاستدامة</td><td>جميع أنشطة التنمية يجب أن تراعي مصالح الأجيال الحالية والقادمة؛ ومعارضة استنزاف الموارد جذرياً</td></tr><tr><td>الوقاية أولاً</td><td>حماية البيئة موجهة بالوقاية؛ وإنشاء نظام تقييم الأثر البيئي لمنع حدوث التلوث</td></tr><tr><td>مسؤولية الملوث</td><td>الجهات المسببة للتلوث البيئي والتدمير الإيكولوجي يجب أن تتحمل مسؤولية المعالجة والتعويض</td></tr><tr><td>المشاركة العامة</td><td>تشجيع مشاركة الجمهور في حماية البيئة؛ وضمان حق الجمهور في المعرفة البيئية والمشاركة</td></tr><tr><td>التنسيق عبر الأبعاد</td><td>حماية البيئة تتقدم بالتنسيق بين الأبعاد؛ وإنشاء آلية تعاون في الحوكمة البيئية عبر الأبعاد</td></tr></tbody></table><h2 id="ثانياً-نطاق-حماية-البيئة" tabindex="-1">ثانياً: نطاق حماية البيئة <a class="header-anchor" href="#ثانياً-نطاق-حماية-البيئة" aria-label="Permalink to &quot;ثانياً: نطاق حماية البيئة&quot;">​</a></h2><p>يشمل النطاق البيئي الذي يحميه هذا القانون جميع النظم الإيكولوجية والعناصر البيئية داخل كون هنغ يوان:</p><ol><li><strong>البيئة الجوية</strong>: بما في ذلك تركيز الطاقة وتوازن مكونات الغلاف الجوي والطبقات الطاقية لكل كوكب.</li><li><strong>البيئة المائية</strong>: بما في ذلك نوعية وكمية المياه السطحية والجوفية والمحيطات والمياه الطاقية بين الأبعاد.</li><li><strong>بيئة التربة</strong>: بما في ذلك نوعية التربة وخصوبتها للترب البرية وعروق المعادن الخاصة بموارد الزراعة.</li><li><strong>التنوع البيولوجي</strong>: بما في ذلك حماية الأنواع والموائل لجميع النباتات والحيوانات والكائنات الدقيقة والكائنات الغريبة.</li><li><strong>البيئة الطاقية</strong>: بما في ذلك تركيز وتوازن توزيع الطاقة الروحية بين السماء والأرض والطاقة الأصلية وشظايا القوانين.</li><li><strong>البيئة المكانية</strong>: بما في ذلك الاستقرار المكاني للأبعاد والشقوق المكانية والسلامة البيئية للفضاء المطوي.</li><li><strong>بيئة مجال الوعي</strong>: بما في ذلك نقاء المعلومات في فضاء الوعي الجماعي ومنع التلوث الروحي.</li></ol><h2 id="ثالثاً-الأنظمة-الرئيسية" tabindex="-1">ثالثاً: الأنظمة الرئيسية <a class="header-anchor" href="#ثالثاً-الأنظمة-الرئيسية" aria-label="Permalink to &quot;ثالثاً: الأنظمة الرئيسية&quot;">​</a></h2><h3 id="أ-نظام-تقييم-الأثر-البيئي" tabindex="-1">(أ) نظام تقييم الأثر البيئي <a class="header-anchor" href="#أ-نظام-تقييم-الأثر-البيئي" aria-label="Permalink to &quot;(أ) نظام تقييم الأثر البيئي&quot;">​</a></h3><p>جميع مشاريع التنمية والبناء التي قد تحدث أثراً بيئياً كبيراً يجب أن تخضع لتقييم الأثر البيئي قبل بدء العمل. يشمل محتوى التقييم: أثر المشروع على العناصر البيئية الجوية والمائية والتربية والبيولوجية والطاقية والمكانية وغيرها، وإجراءات الوقاية والتخفيف، وتقييم المخاطر البيئية وغيرها. ولا يجوز للمشاريع التي لم تجتز تقييم الأثر البيئي بدء البناء.</p><h3 id="ب-نظام-إذن-التصريف-والتحكم-بالكميات-الإجمالية" tabindex="-1">(ب) نظام إذن التصريف والتحكم بالكميات الإجمالية <a class="header-anchor" href="#ب-نظام-إذن-التصريف-والتحكم-بالكميات-الإجمالية" aria-label="Permalink to &quot;(ب) نظام إذن التصريف والتحكم بالكميات الإجمالية&quot;">​</a></h3><p>تطبق الدولة إدارة الإذن والتحكم بالكميات الإجمالية على تصريف الملوثات. يجب على وحدات التصريف الحصول على إذن تصريف الملوثات وتصريف الملوثات وفقاً للأنواع والتركيزات والكميات الإجمالية المحددة في الإذن. تحدد الدولة الكميات الإجمالية لتصريف الملوثات في كل منطقة وكل بُعد وفقاً للقدرة الاستيعابية البيئية، وتوزعها وتنفذها مستوى بمستوى.</p><h3 id="ج-نظام-الخطوط-الحمراء-لحماية-البيئة" tabindex="-1">(ج) نظام الخطوط الحمراء لحماية البيئة <a class="header-anchor" href="#ج-نظام-الخطوط-الحمراء-لحماية-البيئة" aria-label="Permalink to &quot;(ج) نظام الخطوط الحمراء لحماية البيئة&quot;">​</a></h3><p>تحدد الدولة خطوطاً حمراء لحماية البيئة في المناطق ذات القيمة الإيكولوجية الخاصة، بما في ذلك:</p><table tabindex="0"><thead><tr><th>نوع الخط الأحمر</th><th>المحتوى المحمي</th></tr></thead><tbody><tr><td>منطقة حماية الأصل</td><td>مناطق الإنتاج الجوهرية لطاقة أصل الكون؛ ويُحظر جميع أنشطة التنمية</td></tr><tr><td>موائل الأنواع</td><td>الموائل الجوهرية للأنواع النادرة والمهددة بالانقراض؛ ويُحظر التدمير والإزعاج</td></tr><tr><td>منطقة الحاجز الإيكولوجي</td><td>النظم الإيكولوجية الرئيسية المحافظة على التوازن الإيكولوجي الإقليمي؛ والتنمية مقيدة</td></tr><tr><td>الأماكن الزراعية المقدسة</td><td>المناطق الغنية بالطاقة ذات القيمة الزراعية الخاصة؛ ويُطبق استخدام وقائي</td></tr><tr><td>حزام تقاطع الأبعاد</td><td>الأحزمة الانتقالية الإيكولوجية بين الأبعاد؛ ويُحظر التنمية المكانية التدميرية</td></tr></tbody></table><h3 id="د-نظام-الرصد-والإنذار-المبكر-البيئي" tabindex="-1">(د) نظام الرصد والإنذار المبكر البيئي <a class="header-anchor" href="#د-نظام-الرصد-والإنذار-المبكر-البيئي" aria-label="Permalink to &quot;(د) نظام الرصد والإنذار المبكر البيئي&quot;">​</a></h3><p>تنشئ الدولة شبكة رصد بيئي تغطي الكون كله، وتراقب في الزمن الحقيقي تغيرات العناصر البيئية. وبالنسبة لأحداث التلوث البيئي والتدمير الإيكولوجي الكبيرة المحتملة، يُنشأ نظام إنذار مبكر، وتصدر معلومات الإنذار في وقت مناسب وتُطلق الاستجابة الطارئة.</p><h3 id="هـ-نظام-التعويض-البيئي" tabindex="-1">(هـ) نظام التعويض البيئي <a class="header-anchor" href="#هـ-نظام-التعويض-البيئي" aria-label="Permalink to &quot;(هـ) نظام التعويض البيئي&quot;">​</a></h3><p>للمناطق والجماعات المقيدة تنميتها بسبب حماية البيئة الحق في الحصول على تعويض بيئي. تُخصص أموال التعويض البيئي من التراكم العام وعائدات تنمية الموارد، وتُستخدم للتنمية الاقتصادية للمناطق المعوضة وتحسين معيشة السكان.</p><h2 id="رابعاً-التنظيم-البيئي-للأنشطة-الزراعية" tabindex="-1">رابعاً: التنظيم البيئي للأنشطة الزراعية <a class="header-anchor" href="#رابعاً-التنظيم-البيئي-للأنشطة-الزراعية" aria-label="Permalink to &quot;رابعاً: التنظيم البيئي للأنشطة الزراعية&quot;">​</a></h2><p>أثر الأنشطة الزراعية على البيئة مجال خاص لحماية البيئة في كون هنغ يوان؛ ويضع هذا القانون أحكاماً تنظيمية خاصة:</p><ol><li><strong>تنظيم استخراج الطاقة</strong>: يجب أن يتوافق استخراج موارد الزراعة مع مبدأ الاستدامة؛ ويُحظر الاستخراج التدميري المؤدي إلى نضوب الطاقة. ولا يجوز أن يتجاوز حجم الاستخراج السرعة الطبيعية لاستعادة الطاقة الإقليمية.</li><li><strong>معالجة نفايات الزراعة</strong>: يجب معالجة البقايا الطاقية والحبوب المطروحة والآثار المتضررة وغيرها من النفايات الناتجة عن الزراعة وفقاً للوائح؛ ويُحظر الإلقاء العشوائي المسبب لتلوث طاقي.</li><li><strong>التقييم البيئي للزراعة المتقدمة</strong>: قد يكون لاختراقات واعتكافات المزارعين المتقدمين آثار كبيرة على البيئة المحيطة؛ ويجب إجراء تقييم بيئي مسبقاً واتخاذ إجراءات وقائية.</li><li><strong>إذن تنمية الأبعاد</strong>: يجب أن تخضع تنمية الأبعاد الجديدة لتقييم بيئي ومسح إيكولوجي؛ ولا تتم التنمية إلا بعد وضع خطة حماية إيكولوجية.</li><li><strong>حماية موائل الكائنات الغريبة</strong>: تُدرج موائل الكائنات الغريبة ضمن الخطوط الحمراء لحماية البيئة؛ ويُحظر الاستكشاف والتنمية دون إذن.</li></ol><h2 id="خامساً-المسؤولية-القانونية" tabindex="-1">خامساً: المسؤولية القانونية <a class="header-anchor" href="#خامساً-المسؤولية-القانونية" aria-label="Permalink to &quot;خامساً: المسؤولية القانونية&quot;">​</a></h2><p>تتحمل الأفعال المخالفة لأحكام هذا القانون المسؤوليات التالية حسب جسامة الظروف:</p><ul><li>الشروع في البناء دون اجتياز تقييم الأثر البيئي: الأمر بوقف البناء وإعادة الحالة الأصلية ودفع غرامة.</li><li>التصريف الزائد عن المعايير: الأمر بالمعالجة خلال مهلة ودفع غرامة، وفي الحالات الجسيمة الأمر بوقف التشغيل والإغلاق.</li><li>تدمير الخطوط الحمراء لحماية البيئة: الأمر بإعادة الحالة الأصلية ودفع غرامة، وفي الحالات الجسيمة تطبيق المسؤولية الجنائية.</li><li>الاستخراج التدميري لموارد الزراعة: مصادرة العائدات غير المشروعة ودفع غرامة وإلغاء إذن الاستخراج.</li><li>التسبب في حوادث تلوث بيئي كبرى: تحمل مسؤولية التعويض، وفي حال تشكيل جريمة تطبيق المسؤولية الجنائية.</li><li>الإهمال في الواجبات أو إساءة استعمال السلطة من رقباء البيئة: توقيع جزاءات، وفي حال تشكيل جريمة تطبيق المسؤولية الجنائية.</li></ul><h2 id="سادساً-المشاركة-العامة-والدعوى-العامة-البيئية" tabindex="-1">سادساً: المشاركة العامة والدعوى العامة البيئية <a class="header-anchor" href="#سادساً-المشاركة-العامة-والدعوى-العامة-البيئية" aria-label="Permalink to &quot;سادساً: المشاركة العامة والدعوى العامة البيئية&quot;">​</a></h2><p>للجمهور الحق في المشاركة في حماية البيئة، وتشمل السبل المحددة:</p><ol><li>تقديم الآراء والاقتراحات بشأن مشاريع تقييم الأثر البيئي.</li><li>الإبلاغ والشكوى ضد الأفعال الملوثة للبيئة والمدمِّرة للإيكولوجيا.</li><li>تأسيس منظمات حماية البيئة وفقاً للقانون والمشاركة في الرقابة البيئية والأنشطة العامة.</li><li>عن الأفعال الملوثة للبيئة والمدمِّرة للإيكولوجيا والضارة بالمصالح العامة، يمكن لمنظمات حماية البيئة رفع دعوى عامة بيئية أمام محكمة التكافل.</li></ol><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p><em>قانون حماية البيئة</em> هو الضمان القانوني لفلسفة التنمية المستدامة في حضارة التكافل المرساة. بإنشاء أنظمة تقييم الأثر البيئي والخطوط الحمراء لحماية البيئة والتحكم بالكميات الإجمالية وغيرها، يدمج حماية البيئة في جميع أنشطة التنمية والزراعة، ويضمن استدامة أصل الكون والنظام الإيكولوجي، ويحرس أساس البقاء الأبدي لتقدم عشرة آلاف عرق معاً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li><li>39-住房与环境保障 (الإسكان وحماية البيئة)</li><li>15-能量循环与转化法则 (قانون دورة الطاقة وتحويلها)</li><li>53-奇特生命识别标准 (معايير التعرف على الكائنات الغريبة)</li></ul>',34)])])}const p=a(d,[["render",i]]);export{u as __pageData,p as default};
